				const CX2SkillTree::SkillTemplet* pSkillTempletSpritualizedFury 
					= pUnitData->m_UserSkillTree.GetUserSkillTemplet( CX2SkillTree::SI_P_RRF_SPIRITUALIZED_FURY );

