	if( m_hSeqHPUp == INVALID_PARTICLE_SEQUENCE_HANDLE )
		m_hSeqHPUp = g_pX2Game->GetMajorParticle()->CreateSequenceHandle( (CKTDGObject*) this,  L"Plus_Hp01", hpAndMpUpPos );

