	if ( !IsStickShaking() && IsMyUnit() && INVALID_PARTICLE_SEQUENCE_HANDLE != m_hStickShakePrompt )
		g_pX2Game->GetMajorParticle()->DestroyInstanceHandle( m_hStickShakePrompt );
