void CX2GUUser::RidingStartEventProcess()
{
	CommonEventProcess();

	const float EVENT_TIME = 4.5f;

	if( EVENT_TIME <= m_FrameDataFuture.unitCondition.fStateTime )
	{
		StateChange( USI_RIDING_WAIT );
	}
}
